INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10012, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "2024/03/22 14:59:59", 2, "2023/12/15 15:00:00", 2002, 0.0, -470.0, "ネフィ=ネラ", 6.2, 3, 1, 129701, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10013, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "2024/06/22 14:59:59", 3, "2024/03/15 15:00:00", 2002, 0.0, -470.0, "カノン", 3.1, 4, 5, 130301, 1);
