INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10015, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "2024/06/22 14:59:59", 2, "2024/03/15 15:00:00", 2002, 0.0, -470.0, "ナーナ", 0.0, 4, 2, 130401, 1);
