INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10017, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "2024/09/22 14:59:59", 1, "2024/06/15 15:00:00", 2002, 0.0, -470.0, "ホウオウ", 0.0, 5, 1, 130502, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10018, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "2024/09/22 14:59:59", 2, "2024/06/15 15:00:00", 2002, 0.0, -470.0, "ホウオウ", 3.18, 5, 1, 130502, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10019, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "2024/09/22 14:59:59", 4, "2024/06/15 15:00:00", 2002, 0.0, -470.0, "ホウオウ", 0.0, 5, 4, 130503, 3);
