INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10021, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "2024/09/22 14:59:59", 1, "2024/06/15 15:00:00", 2002, 0.0, -470.0, "ネア", 4.8, 5, 2, 123301, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10022, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "2024/12/22 14:59:59", 3, "2024/09/15 15:00:00", 2002, 0.0, -470.0, "カリザ", 4.922, 6, 1, 133301, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10023, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "2024/12/22 14:59:59", 3, "2024/09/15 15:00:00", 2002, 0.0, -470.0, "カリザ", 9.638, 6, 5, 133301, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10024, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "2024/12/22 14:59:59", 1, "2024/09/15 15:00:00", 2002, 0.0, -470.0, "ミーア", 2.88, 6, 2, 133401, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10025, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "2024/12/22 14:59:59", 5, "2024/09/15 15:00:00", 2002, 0.0, -470.0, "ミーア", 4.818, 6, 1, 133401, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10026, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "2025/03/22 14:59:59", 2, "2024/12/15 15:00:00", 2002, 0.0, -470.0, "グレイス", 1.78, 7, 1, 133002, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10027, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "2025/03/22 14:59:59", 1, "2024/12/15 15:00:00", 2002, 0.0, -470.0, "グレイス", 6.15, 7, 7, 133002, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10028, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "2025/03/22 14:59:59", 6, "2024/12/15 15:00:00", 2002, 0.0, -470.0, "ヴァイオレット", 4.28, 7, 2, 133102, 1);
