INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10030, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "2025/06/23 14:59:59", 2, "2025/03/15 15:00:00", 2002, 0.0, -470.0, "ルルィ", 5.53, 8, 1, 136902, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10031, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "2025/06/23 14:59:59", 9, "2025/03/15 15:00:00", 2002, 0.0, -470.0, "ルルィ", 6.05, 8, 7, 136902, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10032, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "2025/06/23 14:59:59", 2, "2025/03/15 15:00:00", 2002, 0.0, -470.0, "デュラン", 0.0, 8, 1, 137001, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10033, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "2025/06/23 14:59:59", 2, "2025/03/15 15:00:00", 2002, 0.0, -470.0, "デュラン", 0.0, 8, 1, 137001, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10034, "おう\n好きなもん持ってきな", "2025/09/23 14:59:59", 2, "2025/06/16 15:00:00", 2002, 0.0, -470.0, "サツキ", 0.0, 9, 2, 135902, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10035, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "2025/09/23 14:59:59", 1, "2025/06/16 15:00:00", 2002, 0.0, -470.0, "サツキ", 4.935, 9, 6, 135902, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10036, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "2025/09/23 14:59:59", 2, "2025/06/16 15:00:00", 2002, 0.0, -470.0, "ユキノ", 7.441, 9, 5, 135802, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10037, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "2025/09/23 14:59:59", 7, "2025/06/16 15:00:00", 2002, 0.0, -470.0, "ユキノ", 0.0, 9, 7, 135802, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10038, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "2025/12/22 14:59:59", 2, "2025/09/16 15:00:00", 2002, 0.0, -470.0, "クルル", 2.295, 10, 2, 130901, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10039, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "2025/12/22 14:59:59", 1, "2025/09/16 15:00:00", 2002, 0.0, -470.0, "クルル", 6.281, 10, 6, 130901, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10040, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "2025/12/22 14:59:59", 2, "2025/09/16 15:00:00", 2002, 0.0, -470.0, "ヴォルガーノ", 5.549, 10, 1, 137701, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10041, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "2025/12/22 14:59:59", 3, "2025/09/16 15:00:00", 2002, 0.0, -470.0, "ヴォルガーノ", 2.64, 10, 6, 137701, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10042, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "2026/03/23 11:59:59", 7, "2025/12/15 15:00:00", 2002, 0.0, -470.0, "ライラエル", 7.642, 11, 4, 132801, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10043, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "2026/03/23 11:59:59", 1, "2025/12/15 15:00:00", 2002, 0.0, -470.0, "ライラエル", 0.0, 11, 1, 132802, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10044, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "2026/03/23 11:59:59", 1, "2025/12/15 15:00:00", 2002, 0.0, -470.0, "クローチェ", 0.0, 11, 1, 134502, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10045, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "2026/03/23 11:59:59", 2, "2025/12/15 15:00:00", 2002, 0.0, -470.0, "クローチェ", 3.72, 11, 1, 134501, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10046, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "2026/06/22 11:59:59", 2, "2026/03/16 12:00:00", 2002, 0.0, -470.0, "ネフィ＝ネラ", 4.991, 12, 1, 138201, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10047, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "2026/06/22 11:59:59", 1, "2026/03/16 12:00:00", 2002, 0.0, -470.0, "ネフィ＝ネラ", 3.877, 12, 4, 138201, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10048, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "2026/06/22 11:59:59", 4, "2026/03/16 12:00:00", 2002, 0.0, -470.0, "アラクネ", 1.71, 12, 6, 136001, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10049, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "2026/06/22 11:59:59", 5, "2026/03/16 12:00:00", 2002, 0.0, -470.0, "アラクネ", 5.32, 12, 2, 136001, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10050, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "2026/09/22 11:59:59", 9, "2026/06/15 12:00:00", 2002, 0.0, -470.0, "アネモネ", 3.727, 13, 4, 135401, 1);
